4:import os from 'node:os';
5:import path from 'node:path';
6:import { commitBatch, recoverLedger } from '../src/ledger.js';
7:
8:async function workspace(t) {
9:  const directory = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-visible-'));
10:  t.after(() => fs.rm(directory, { recursive: true, force: true }));
11:  return directory;
12:}
13:
14:test('commits balances and reads them in a later invocation', async t => {
15:  const directory = await workspace(t);
16:  const batch = { id: 'seed', entries: [{ key: 'cash', delta: 9 }, { key: 'cash', delta: -2 }] };
17:  const expected = { revision: 1, balances: { cash: 7 }, receipts: [batch] };
18:  assert.deepEqual(await commitBatch(directory, batch), expected);
19:  assert.deepEqual(await recoverLedger(directory), expected);
20:});
21:
22:test('a repeated successful batch is idempotent', async t => {
23:  const directory = await workspace(t);
24:  const batch = { id: 'once', entries: [{ key: 'cash', delta: 3 }] };
25:  const state = await commitBatch(directory, batch);
26:  assert.deepEqual(await commitBatch(directory, batch), state);
27:});
28:
29:test('reopening after interrupted publication does not double the balance', async t => {
30:  const directory = await workspace(t);
31:  const batch = { id: 'interrupted', entries: [{ key: 'cash', delta: 7 }] };
