const b = { id: 'b', entries: [{ key: 'cash', delta: -2 }, { key: 'bank', delta: 4 }] };
const final = { revision: 2, balances: { cash: 4, bank: 4 }, receipts: [a, b] };
let cases = 0;

async function dir() { return fs.mkdtemp(path.join(os.tmpdir(), 'ledger-smoke-')); }

function faulty(failAt, method) {
  let n = 0;
