// Overflow with a pending prepared transaction must not write anything.
{
  const d = await dir();
  const stop = new Error('stop');
  await assert.rejects(commitBatch(d, a, { checkpoint: async p => { if (p === 'prepared') throw stop; } }), e => e === stop);
  await assert.rejects(commitBatch(d, { id: 'x', entries: [{ key: 'cash', delta: Number.MAX_SAFE_INTEGER }] }), { code: 'ERR_INVALID_BATCH' });
  await fs.access(path.join(d, 'pending.json'));
  assert.deepEqual(await recoverLedger(d), { revision: 1, balances: { cash: 6 }, receipts: [a] });
  cases++;
}
