import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function invalid() {
  return fail('ERR_INVALID_BATCH', 'Invalid batch');
}

function corrupt(file) {
  return fail('ERR_LEDGER_CORRUPT', `Corrupt ledger data in ${file}`);
}

function emptyLedger() {
  return { revision: 0, balances: {}, receipts: [] };
}

// Returns a normalized `{id, entries}` copy, or null when the shape is invalid.
function normalizeBatch(batch) {
  if (!batch || typeof batch !== 'object' || typeof batch.id !== 'string' || batch.id === '' || !Array.isArray(batch.entries)) return null;
  const entries = [];
  for (let i = 0; i < batch.entries.length; i++) {
    const entry = batch.entries[i];
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    entries.push({ key: entry.key, delta: entry.delta });
  }
  return { id: batch.id, entries };
}

function normalizeSnapshot(value) {
  if (!value || typeof value !== 'object' || !Number.isSafeInteger(value.revision) || value.revision < 0) return null;
  const { balances: stored, receipts: storedReceipts } = value;
  if (!stored || typeof stored !== 'object' || Array.isArray(stored) || !Array.isArray(storedReceipts)) return null;
  const balances = {};
  for (const key of Object.keys(stored)) {
    if (!KEY.test(key) || !Number.isSafeInteger(stored[key])) return null;
    balances[key] = stored[key];
  }
  const receipts = [];
  for (let i = 0; i < storedReceipts.length; i++) {
    const receipt = normalizeBatch(storedReceipts[i]);
    if (!receipt) return null;
    receipts.push(receipt);
  }
  return { revision: value.revision, balances, receipts };
}

function sameEntries(a, b) {
  if (a.length !== b.length) return false;
  return a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

// Returns the next snapshot, or null when a resulting balance is not a safe integer.
function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) return null;
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

async function readJson(io, directory, name) {
  let text;
  try { text = await io.readFile(path.join(directory, name), 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

// Stage to `<name>.tmp`, then atomically replace `<name>.json`.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

// Reads durable state without writing. `state` is the committed snapshot including any
// prepared transaction; `publish`/`pending` say which durable steps remain to settle it.
async function load(io, directory) {
  const stored = await readJson(io, directory, 'ledger.json');
  const ledger = stored === undefined ? emptyLedger() : normalizeSnapshot(stored);
  if (!ledger) throw corrupt('ledger.json');

  const storedPending = await readJson(io, directory, 'pending.json');
  if (storedPending === undefined) return { state: ledger, publish: false, pending: false };
  const batch = normalizeBatch(storedPending);
  if (!batch || !Number.isSafeInteger(storedPending.revision)) throw corrupt('pending.json');

  const receipt = ledger.receipts.find(item => item.id === batch.id);
  if (receipt) {
    // Already published; only cleanup is left.
    if (!sameEntries(receipt.entries, batch.entries)) throw corrupt('pending.json');
    return { state: ledger, publish: false, pending: true };
  }
  if (ledger.revision !== storedPending.revision) throw corrupt('pending.json');
  const next = apply(ledger, batch);
  if (!next) throw corrupt('pending.json');
  return { state: next, publish: true, pending: true };
}

async function settle(io, directory, loaded) {
  if (loaded.publish) await save(io, directory, 'ledger', loaded.state);
  if (loaded.pending) await removePending(io, directory);
}

export async function recoverLedger(directory, options = {}) {
  const io = options.io ?? fs;
  await io.mkdir(directory, { recursive: true });
  const loaded = await load(io, directory);
  await settle(io, directory, loaded);
  return loaded.state;
}

export async function commitBatch(directory, batch, options = {}) {
  const io = options.io ?? fs;
  const checkpoint = options.checkpoint;
  const normalized = normalizeBatch(batch);
  if (!normalized) throw invalid();

  const loaded = await load(io, directory);
  const state = loaded.state;
  const receipt = state.receipts.find(item => item.id === normalized.id);
  let next = null;
  if (!receipt) {
    next = apply(state, normalized);
    if (!next) throw invalid();
  }

  // Finish any earlier prepared transaction before handling this batch.
  await io.mkdir(directory, { recursive: true });
  await settle(io, directory, loaded);

  if (receipt) {
    if (!sameEntries(receipt.entries, normalized.entries)) {
      throw fail('ERR_BATCH_CONFLICT', 'Batch ID already used with different entries');
    }
    return state;
  }

  await save(io, directory, 'pending', { revision: state.revision, id: normalized.id, entries: normalized.entries });
  if (checkpoint) await checkpoint('prepared');
  // Balances and receipt publish together in one atomic rename.
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

